function countSubarrays(nums, k) {
  const maxValue = Math.max(...nums);
  let maxCount = 0;
  let left = 0;
  let answer = 0;
  for (let right = 0; right < nums.length; right++) {
    if (nums[right] === maxValue) {
      maxCount++;
    }
    while (maxCount >= k) {
      if (nums[left] === maxValue) {
        maxCount--;
      }
      left++;
    }
    answer += left;
  }
  return answer;
}

